/**
 * @suppress
 */
public object FfiConverterTypeCampusEngine: FfiConverter<CampusEngine, Pointer> {

    override fun lower(value: CampusEngine): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): CampusEngine {
        return CampusEngine(value)
    }

    override fun read(buf: ByteBuffer): CampusEngine {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: CampusEngine) = 8UL

    override fun write(value: CampusEngine, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



