sealed class CampusException(message: String): kotlin.Exception(message) {
        
        class Database(message: String) : CampusException(message)
        
        class NotFound(message: String) : CampusException(message)
        
        class InvalidInput(message: String) : CampusException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CampusException> {
        override fun lift(error_buf: RustBuffer.ByValue): CampusException = FfiConverterTypeCampusError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeCampusError : FfiConverterRustBuffer<CampusException> {
    override fun read(buf: ByteBuffer): CampusException {
        
            return when(buf.getInt()) {
            1 -> CampusException.Database(FfiConverterString.read(buf))
            2 -> CampusException.NotFound(FfiConverterString.read(buf))
            3 -> CampusException.InvalidInput(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: CampusException): ULong {
        return 4UL
    }

    override fun write(value: CampusException, buf: ByteBuffer) {
        when(value) {
            is CampusException.Database -> {
                buf.putInt(1)
                Unit
            }
            is CampusException.NotFound -> {
                buf.putInt(2)
                Unit
            }
            is CampusException.InvalidInput -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




